basic.code:
// A collection is a set of documents; each document has an id and fields
{"collection": "categories"}

// The customers: no fixed schema, c6 has no email field
{"collection": "customers"}

// Read one document by its id: a direct lookup, no query
{"collection": "products", "id": "p04"}

{"collection": "orders", "id": "o07"}

// Only the fields this document really has
{"collection": "customers", "id": "c6"}

// select: return only some fields (a projection)
{"collection": "products", "select": "name,price"}

// _id always comes back: it is the document's name, not a field
{"collection": "products", "select": "name,stock,tags"}

// Products in category cat2 (where field == value)
{"collection": "products", "where": {"category": "cat2"}, "select": "name,price"}

// Booleans work the same way
{"collection": "products", "where": {"active": false}, "select": "name,stock"}

// Customers who live in Madrid
{"collection": "customers", "where": {"city": "Madrid"}, "select": "name,city,joined"}

// Cheaper than 2 euros
{"collection": "products", "where": {"price": {"lt": 2}}, "select": "name,price"}

// At least 30 units in stock
{"collection": "products", "where": {"stock": {"gte": 30}}, "select": "name,stock"}

// Strings compare too: customers who joined in 2024 or later
{"collection": "customers", "where": {"joined": {"gte": "2024-01-01"}}, "select": "name,joined"}

// Two conditions on different fields: both must hold (AND)
{"collection": "products", "where": {"category": "cat3", "price": {"lt": 3}}, "select": "name,price"}

// A range on one field: from 2 up to (not including) 4 euros
{"collection": "products", "where": {"price": {"gte": 2, "lt": 4}}, "select": "name,price"}

// Inequalities on two fields
{"collection": "products", "where": {"price": {"lt": 4}, "stock": {"gt": 20}}, "select": "name,price,stock"}

// in: the field equals any value of the list
{"collection": "orders", "where": {"status": {"in": ["new", "paid"]}}, "select": "customer,status,total"}

// nin (not-in): none of the values
{"collection": "products", "where": {"category": {"nin": ["cat1", "cat2"]}}, "select": "name,category"}

// contains: the tags array holds "sweet"
{"collection": "products", "where": {"tags": {"contains": "sweet"}}, "select": "name,tags"}

// containsAny: the array holds at least one of the values
{"collection": "products",
 "where": {"tags": {"containsAny": ["tea", "coffee", "juice"]}}, "select": "name,tags"}

// Most expensive first
{"collection": "products", "order": "price desc", "select": "name,price"}

// Two fields: by category, and inside each one by price (high to low)
{"collection": "products", "order": "category, price desc", "select": "name,category,price"}

// The three cheapest products
{"collection": "products", "order": "price", "limit": 3, "select": "name,price"}

// Pages of four: page 1, then page 2 (skip the first four)
{"collection": "products", "order": "name", "limit": 4, "select": "name,price"}
{"collection": "products", "order": "name", "limit": 4, "offset": 4, "select": "name,price"}

// All customers: c6 has no email field at all
{"collection": "customers", "count": true}

// Ordering by a field leaves out the documents without it
{"collection": "customers", "order": "email", "select": "name,email"}

// So does "not equal": 8 customers, but only 6 come back
{"collection": "customers", "where": {"email": {"neq": "ana@example.com"}}, "select": "name,email"}

// How many products? An aggregation query returns one row
{"collection": "products", "count": true}

// Count with a filter
{"collection": "products", "where": {"stock": 0}, "count": true}

// Orders already shipped
{"collection": "orders", "where": {"status": "shipped"}, "count": true}

// Units in stock across the whole shop
{"collection": "products", "sum": "stock"}

// Average price of the dairy products (cat3)
{"collection": "products", "where": {"category": "cat3"}, "avg": "price"}

// count, sum and avg in the same query
{"collection": "reviews", "where": {"product": "p04"}, "count": true, "sum": "rating", "avg": "rating"}

// A field can be a map with its own fields
{"collection": "stores", "insert": [
  {"_id": "s1", "name": "Centre", "address": {"city": "Madrid", "zip": "28001"}},
  {"_id": "s2", "name": "Harbour", "address": {"city": "Bilbao", "zip": "48001"}},
  {"_id": "s3", "name": "Retiro", "address": {"city": "Madrid", "zip": "28009"}}
]}

// Dot notation reaches inside the map: filter, order and select
{"collection": "stores",
 "where": {"address.city": "Madrid"}, "order": "address.zip desc", "select": "name,address.zip"}

