basic.code:
// _id chooses the document id; the rest are its fields
{"collection": "categories", "insert": {"_id": "cat5", "name": "Frozen"}}

// Several documents at once
{"collection": "products", "insert": [
  {"_id": "p13", "name": "Ice cream", "category": "cat5", "price": 4.2, "stock": 10, "active": true, "tags": ["sweet"]},
  {"_id": "p14", "name": "Frozen peas", "category": "cat5", "price": 1.9, "stock": 24, "active": true, "tags": []}
]}

{"collection": "products", "where": {"category": "cat5"}, "select": "name,price,stock"}

// Without _id, Firestore makes up a random 20-character id
{"collection": "reviews", "insert": [
  {"product": "p07", "rating": 5, "comment": "Fresh every day"},
  {"product": "p07", "rating": 3, "comment": "Fine"}
]}

// The ids change on every run: query by fields instead
{"collection": "reviews", "where": {"product": "p07"}, "count": true, "avg": "rating"}

// Orange juice is back in stock: only "stock" changes
{"collection": "products", "update": {"id": "p06", "set": {"stock": 20}}}

// A field that did not exist is added
{"collection": "products", "update": {"id": "p05", "set": {"price": 4.25, "featured": true}}}

{"collection": "products", "where": {"category": "cat2"}, "select": "name,price,stock,featured"}

// Every product without stock becomes inactive
{"collection": "products", "update": {"where": {"stock": 0}, "set": {"active": false}}}

// Every bakery product gets a 10% discount label
{"collection": "products", "update": {"where": {"category": "cat1"}, "set": {"discount": 10}}}

{"collection": "products",
 "where": {"category": {"in": ["cat1", "cat2"]}}, "select": "name,stock,active,discount"}

// Delete one document by its id
{"collection": "reviews", "delete": "r5"}

// Delete every document that matches a filter
{"collection": "reviews", "delete": {"where": {"rating": {"lte": 2}}}}

{"collection": "reviews", "order": "rating desc, product", "select": "product,rating,comment"}

// The catalogue page: active products with stock, cheapest first
{"collection": "products", "where": {"active": true, "stock": {"gt": 0}}, "count": true}

{"collection": "products",
 "where": {"active": true, "stock": {"gt": 0}, "price": {"lt": 5}},
 "order": "price",
 "limit": 6,
 "select": "name,price,stock,tags"}

advanced.code:
// An order keeps its lines inside: one read brings everything
{"collection": "orders", "id": "o07"}

// The items array travels with every order you read
{"collection": "orders", "where": {"customer": "c1"}, "select": "ordered,total,items"}

// If you only need the header, ask only for the header
{"collection": "orders", "where": {"customer": "c1"}, "order": "ordered", "select": "ordered,status,total"}

// contains on an array of maps needs the WHOLE map, every field equal
{"collection": "orders",
 "where": {"items": {"contains": {"product": "p04", "qty": 1, "price": 9.9}}}, "select": "customer,total"}

// The fix: keep a plain array of product ids next to the items
{"collection": "orders", "update": {"id": "o02", "set": {"products": ["p04", "p02"]}}}
{"collection": "orders", "update": {"id": "o05", "set": {"products": ["p04"]}}}
{"collection": "orders", "update": {"id": "o08", "set": {"products": ["p04", "p05", "p12"]}}}

// Now "every order with espresso beans" is a simple query
{"collection": "orders",
 "where": {"products": {"contains": "p04"}}, "select": "customer,status,total,products"}

// A subcollection hangs from one document: orders/o01/notes
{"collection": "orders/o01/notes", "insert": [
  {"_id": "n1", "text": "Call before delivery", "by": "e5", "at": "2024-03-01 10:05"},
  {"_id": "n2", "text": "Customer asked for a bag", "by": "e3", "at": "2024-03-01 09:40"}
]}
{"collection": "orders/o03/notes",
 "insert": {"_id": "n1", "text": "Paid by card", "by": "e5", "at": "2024-03-15 18:20"}}

// The parent order does not change: notes are not one of its fields
{"collection": "orders", "id": "o01"}

// Query one subcollection like any other collection
{"collection": "orders/o01/notes", "order": "at", "select": "at,by,text"}

{"collection": "orders/o01/notes", "insert": [
  {"_id": "n1", "text": "Call before delivery", "by": "e5"},
  {"_id": "n2", "text": "Customer asked for a bag", "by": "e3"}
]}
{"collection": "orders/o03/notes", "insert": {"_id": "n1", "text": "Paid by card", "by": "e5"}}
{"collection": "orders/o08/notes", "insert": {"_id": "n1", "text": "Fragile: glass jar", "by": "e4"}}

// group: every collection called "notes", under any order
{"collection": "notes", "group": true, "count": true}

// The notes written by e5, whichever order they belong to
{"collection": "notes", "group": true, "where": {"by": "e5"}, "order": "text", "select": "by,text"}

// No joins: copy the customer's name into each of their orders
{"collection": "orders", "update": {"where": {"customer": "c1"}, "set": {"customerName": "Ana García"}}}
{"collection": "orders", "update": {"where": {"customer": "c2"}, "set": {"customerName": "Luis Pérez"}}}
{"collection": "orders", "update": {"where": {"customer": "c3"}, "set": {"customerName": "Marta López"}}}

// Now one query is enough to list orders with names
{"collection": "orders",
 "where": {"customer": {"in": ["c1", "c2", "c3"]}}, "order": "ordered", "select": "customerName,ordered,total"}

{"collection": "orders", "update": {"where": {"customer": "c1"}, "set": {"customerName": "Ana García"}}}

// Ana changes her name: first the customer document...
{"collection": "customers", "update": {"id": "c1", "set": {"name": "Ana García Ruiz"}}}

// ...then every copy of it (one write per order)
{"collection": "orders", "update": {"where": {"customer": "c1"}, "set": {"customerName": "Ana García Ruiz"}}}

{"collection": "orders", "where": {"customer": "c1"}, "select": "customer,customerName,total"}

{"collection": "stores", "insert": [
  {"_id": "s1", "name": "Centre", "address": {"city": "Madrid", "zip": "28001"},
   "hours": {"open": "09:00", "close": "21:00"}},
  {"_id": "s2", "name": "Harbour", "address": {"city": "Bilbao", "zip": "48001"},
   "hours": {"open": "10:00", "close": "20:00"}},
  {"_id": "s3", "name": "Retiro", "address": {"city": "Madrid", "zip": "28009"},
   "hours": {"open": "08:30", "close": "22:00"}}
]}

// A map in "set" replaces the whole map: send every key you want to keep
{"collection": "stores", "update": {"id": "s2", "set": {"hours": {"open": "10:00", "close": "22:00"}}}}

// Dot paths inside maps work in where and order
{"collection": "stores",
 "where": {"hours.close": {"gte": "21:00"}}, "order": "hours.close desc, name", "select": "name,hours"}

