advanced.code:
// Give the dairy products a tag (set replaces the whole array)
{"collection": "products", "update": {"id": "p07", "set": {"tags": ["dairy"]}}}
{"collection": "products", "update": {"id": "p08", "set": {"tags": ["dairy", "sweet"]}}}
{"collection": "products", "update": {"id": "p09", "set": {"tags": ["cheese", "dairy"]}}}

// One array-contains: products tagged "sweet" that are dairy (cat3)
{"collection": "products",
 "where": {"tags": {"contains": "sweet"}, "category": "cat3"}, "select": "name,tags"}

// containsAny: dairy or fresh
{"collection": "products",
 "where": {"tags": {"containsAny": ["dairy", "fresh"]}}, "order": "name", "select": "name,tags"}

// Page 3 with offset: Firestore still reads (and bills) the 8 skipped docs
{"collection": "products", "order": "name", "limit": 4, "offset": 8, "select": "name,price"}

// A cursor instead: page 1, remember the last name...
{"collection": "products", "order": "name", "limit": 4, "select": "name,price"}

// ...and start the next page right after it (startAfter "Croissant")
{"collection": "products",
 "where": {"name": {"gt": "Croissant"}}, "order": "name", "limit": 4, "select": "name,price"}

// Firestore has no GROUP BY: one aggregation query per group
{"collection": "orders", "where": {"status": "new"}, "count": true, "sum": "total"}
{"collection": "orders", "where": {"status": "paid"}, "count": true, "sum": "total"}
{"collection": "orders", "where": {"status": "cancelled"}, "count": true, "sum": "total"}

// Or a filter that covers several groups at once
{"collection": "orders", "where": {"status": {"in": ["paid", "shipped"]}}, "count": true}

{"collection": "orders", "where": {"status": "shipped"}, "count": true, "sum": "total", "avg": "total"}

// Order o08 says who bought it and which products
{"collection": "orders", "id": "o08"}

// Second read: the customer, by the id stored in the order
{"collection": "customers", "id": "c7"}

// Third read: one product (in an app, all of them in one batch)
{"collection": "products", "id": "p04"}

// Fourth read: the reviews of its three products, in one "in" query
{"collection": "reviews",
 "where": {"product": {"in": ["p04", "p05", "p12"]}}, "order": "product", "select": "product,rating,comment"}

// The truth: count and sum the orders of customer c1
{"collection": "orders", "where": {"customer": "c1"}, "count": true, "sum": "total"}

// Store the result in the customer so lists don't recompute it
{"collection": "customers", "update": {"id": "c1", "set": {"orders": 3, "spent": 34.95}}}

// A new order: write the order AND update the counters
{"collection": "orders",
 "insert": {"_id": "o11", "customer": "c1", "ordered": "2024-06-10", "status": "new",
            "total": 5.0, "items": [{"product": "p05", "qty": 1, "price": 5.0}]}}
{"collection": "customers", "update": {"id": "c1", "set": {"orders": 4, "spent": 39.95}}}

{"collection": "customers", "where": {"city": "Madrid"}, "select": "name,orders,spent"}

// Each user's cart lives under their own document: users/{uid}/cart
{"collection": "users/u1/cart", "insert": [
  {"_id": "p01", "qty": 2},
  {"_id": "p12", "qty": 1}
]}
{"collection": "users/u2/cart", "insert": {"_id": "p04", "qty": 1}}

// With rules, u1 may read only users/u1/...; here (emulator, owner) all is open
{"collection": "cart", "group": true, "count": true}

{"collection": "users/u1/cart", "select": "qty"}

// p12 exists: the update works
{"collection": "products", "update": {"id": "p12", "set": {"stock": 20}}}

// A typo in the id: p21 does not exist, so the update fails
{"collection": "products", "update": {"id": "p21", "set": {"stock": 20}}}

// ISO dates as strings sort like dates: "2024-04-02" < "2024-05-01"
{"collection": "orders",
 "where": {"ordered": {"gte": "2024-04-01", "lt": "2024-05-01"}}, "select": "ordered,total"}

// Sales in May
{"collection": "orders",
 "where": {"ordered": {"gte": "2024-05-01", "lt": "2024-06-01"}}, "count": true, "sum": "total"}

// The latest five orders
{"collection": "orders", "order": "ordered desc", "limit": 5, "select": "customer,ordered,status,total"}

// Equality on one field + order on another: needs a composite index
// (status ASC, total DESC) in production; the emulator does not ask
{"collection": "orders",
 "where": {"status": "shipped"}, "order": "total desc", "select": "customer,status,total"}

// Equality + range on another field: index (status, ordered)
{"collection": "orders",
 "where": {"status": "paid", "ordered": {"gte": "2024-05-01"}}, "order": "ordered", "select": "customer,ordered,total"}

// 8 customers in all
{"collection": "customers", "count": true}

// "Not from Madrid": 6 customers
{"collection": "customers", "where": {"city": {"neq": "Madrid"}}, "count": true}

// "Email is not Ana's": 6 too, because c6 has no email field
{"collection": "customers", "where": {"email": {"neq": "ana@example.com"}}, "count": true}

// nin also skips documents without the field, and sorts by it
{"collection": "employees", "where": {"manager": {"nin": ["e1"]}}, "select": "name,manager"}

// Reviews as subcollections of each product
{"collection": "products/p01/reviews", "insert": [{"_id": "r1", "rating": 5}, {"_id": "r2", "rating": 4}]}
{"collection": "products/p04/reviews", "insert": [{"_id": "r1", "rating": 3}, {"_id": "r2", "rating": 5}]}
{"collection": "products/p12/reviews", "insert": [{"_id": "r1", "rating": 2}, {"_id": "r2", "rating": 4}]}

// One product: the subcollection itself
{"collection": "products/p04/reviews", "count": true, "avg": "rating"}

// The whole shop: a collection group aggregation
{"collection": "reviews", "group": true, "count": true, "avg": "rating"}

// Good reviews anywhere (top-level "reviews" too: same name)
{"collection": "reviews", "group": true, "where": {"rating": {"gte": 4}}, "count": true}

// db.table('products').list(where: {'price': 'lt.3'}, order: 'price', limit: 5)
{"collection": "products", "where": {"price": {"lt": 3}}, "order": "price", "limit": 5}

// db.table('products').get('p09')
{"collection": "products", "id": "p09"}

// db.table('products').update('p09', {'stock': 12})
{"collection": "products", "update": {"id": "p09", "set": {"stock": 12}}}

// db.table('orders').list(where: {'status': 'new'}, order: 'total.desc')
{"collection": "orders",
 "where": {"status": "new"}, "order": "total desc", "select": "customer,ordered,total"}

// The tiles: one aggregation per figure
{"collection": "orders", "count": true, "sum": "total"}
{"collection": "orders", "where": {"status": "new"}, "count": true}
{"collection": "orders", "where": {"status": "shipped"}, "sum": "total"}
{"collection": "products", "where": {"stock": {"lt": 10}}, "count": true}

// Orders still to prepare (new or paid), newest first
{"collection": "orders",
 "where": {"status": {"in": ["new", "paid"]}},
 "order": "ordered desc",
 "select": "customer,ordered,status,total"}
